grammar Flat {
 @package: commonprobe
 @whitespace: none
 @root @mapping(Node) @commonField(text,maybe,many,mode)
 Root ::= A | B;
 @enum Mode ::= 'on' | 'off';
 @mapping(A, params=[text,maybe,many,mode])
 A ::= 'a' '😀' @text '[' [ 'x' @maybe ] ']' '{' { 'z' @many } '}' Mode @mode;
 @mapping(B, params=[text,maybe,many,mode])
 B ::= 'b' 'é' @text '[' [ 'x' @maybe ] ']' '{' { 'z' @many } '}' Mode @mode;
}

grammar Dotted {
 @package: commonprobe
 @whitespace: none
 @root @mapping(Node) @commonField(text,maybe,many,mode)
 Root ::= A | B;
 @enum Mode ::= 'on' | 'off';
 @mapping(Node.A, params=[text,maybe,many,mode])
 A ::= 'a' '😀' @text '[' [ 'x' @maybe ] ']' '{' { 'z' @many } '}' Mode @mode;
 @mapping(Node.B, params=[text,maybe,many,mode])
 B ::= 'b' 'é' @text '[' [ 'x' @maybe ] ']' '{' { 'z' @many } '}' Mode @mode;
}

grammar Nodes {
 @package: commonprobe
 @root @mapping(Node) @commonField(child)
 Root ::= A | B;
 @mapping(A,params=[child]) A ::= 'a' Leaf @child;
 @mapping(B,params=[child]) B ::= 'b' Leaf @child;
 @mapping(Leaf,params=[value]) Leaf ::= 'l' @value;
}

grammar Numeric {
 @package: commonprobe
 token NUMBER = org.unlaxer.parser.elementary.NumberParser
 @root @mapping(Node) @commonField(value)
 Root ::= A | B;
 @mapping(A,params=[value]) A ::= 'a' NUMBER @value;
 @mapping(B,params=[value]) B ::= 'b' NUMBER @value;
}

grammar EnumContainers {
 @package: commonprobe
 @root @mapping(Node) @commonField(maybe,many)
 Root ::= A | B;
 @enum Mode ::= 'on' | 'off';
 Alias ::= Mode;
 @mapping(A,params=[maybe,many]) A ::= 'a' '[' [ Mode @maybe ] ']' '{' { Mode @many } '}';
 @mapping(B,params=[maybe,many]) B ::= 'b' '[' [ Alias @maybe ] ']' '{' { Alias @many } '}';
}

grammar Nested {
 @package: commonprobe
 @whitespace: none
 @root @mapping(Node) @commonField(text,maybe,many,mode)
 Root ::= Branch | C;
 @mapping(Branch) Branch ::= A | B;
 @mapping(C,params=[text,maybe,many,mode]) C ::= 'c' '😀' @text '[' [ 'x' @maybe ] ']' '{' { 'z' @many } '}' Mode @mode;
 @enum Mode ::= 'on' | 'off';
 @mapping(A, params=[text,maybe,many,mode])
 A ::= 'a' '😀' @text '[' [ 'x' @maybe ] ']' '{' { 'z' @many } '}' Mode @mode;
 @mapping(B, params=[text,maybe,many,mode])
 B ::= 'b' 'é' @text '[' [ 'x' @maybe ] ']' '{' { 'z' @many } '}' Mode @mode;
}

grammar NodeContainers {
 @package: commonprobe
 @root @mapping(Node) @commonField(maybe,many)
 Root ::= A | B;
 @mapping(A,params=[maybe,many]) A ::= 'a' '[' [ Leaf @maybe ] ']' '{' { Leaf @many } '}';
 @mapping(B,params=[maybe,many]) B ::= 'b' '[' [ Leaf @maybe ] ']' '{' { Leaf @many } '}';
 @mapping(Leaf,params=[value]) Leaf ::= 'l' @value;
}

grammar MixedFields {
 @package: commonprobe
 @whitespace: none
 @root @mapping(Node) @commonField(value,maybe,many)
 Root ::= A | B;
 @enum Mode ::= 'on' | '😀';
 @enum Heat ::= 'hot' | 'cold';
 @mapping(Leaf,params=[text]) Leaf ::= '<' 'node' @text '>';
 Item ::= Mode | Heat | Leaf | 'text';
 @mapping(A,params=[value,maybe,many]) A ::= 'a' Item @value '[' [Item] @maybe ']' '{' {Item} @many '}';
 @mapping(B,params=[value,maybe,many]) B ::= 'b' Item @value '[' [Item] @maybe ']' '{' {Item} @many '}';
}

java:
java.util.function.Function<Object,String> f=v->{
 if(v instanceof MixedFieldsAST.EnumValue e) {var x=e.value();return x.getDeclaringClass().getSimpleName()+":"+(x instanceof MixedFieldsAST.Mode m?m.text():((MixedFieldsAST.Heat)x).text());}
 if(v instanceof MixedFieldsAST.Leaf l)return "node:"+l.text();
 if(v instanceof String text)return "text:"+text;
 throw new AssertionError(v);
};return f.apply(node.value())+"|"+node.maybe().map(f).orElse("-")+"|"+node.many().stream().map(f).collect(java.util.stream.Collectors.joining(","));

