grammar SharedMixedFields {
 @package: commonprobe
 @whitespace: none
 @root @mapping(Node) @commonField(value,maybe,many)
 Root ::= AEnum | AText | ANode | B;
 @enum Mode ::= 'on' | '😀';
 @enum Heat ::= 'hot' | 'cold';
 @mapping(Leaf,params=[text]) Leaf ::= '<' 'node' @text '>';
 Item ::= Mode | Heat | Leaf | 'text';
 @mapping(A,params=[value,maybe,many]) AEnum ::= 'm' Mode @value '[' [Mode] @maybe ']' '{' {Mode} @many '}';
 @mapping(A,params=[value,maybe,many]) AText ::= 't' 'text' @value '[' ['text'] @maybe ']' '{' {'text'} @many '}';
 @mapping(A,params=[value,maybe,many]) ANode ::= 'n' Leaf @value '[' [Leaf] @maybe ']' '{' {Leaf} @many '}';
 @mapping(B,params=[value,maybe,many]) B ::= 'b' Item @value '[' [Item] @maybe ']' '{' {Item} @many '}';
}

